import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"59、【涣】 坎下巽上","description":"周易尚氏学 - 59、【涣】 坎下巽上","frontmatter":{"title":"59、【涣】 坎下巽上","description":"周易尚氏学 - 59、【涣】 坎下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/064.md","filePath":"zh/classics/shangshi/064.md"}'),s={name:"zh/classics/shangshi/064.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_59、【涣】-坎下巽上" tabindex="-1">59、【涣】 坎下巽上 <a class="header-anchor" href="#_59、【涣】-坎下巽上" aria-label="Permalink to “59、【涣】 坎下巽上”">​</a></h1><p>旧解皆以风行水上。涣散为说。然如涣王居。涣其躬等爻辞。散义皆不通。按太玄拟涣为文。司马光云。扬子盖读涣为焕。案涣即有文义。淮南子说山训。夫玉润泽而有光。涣乎其有似也。注文采似君子也。后汉书延笃传。涣烂其溢目。注涣烂文章貌。是涣本有文义。故归藏作奂。礼檀弓。美哉奂焉。释文奂本亦作焕。是扬子之读。与古训合。卦坎为赤。震为玄黄。巽为白。而风行水上。文理烂然。故为文也。为文则于爻辞无扦格矣。震为王。艮为庙。假至也。言王有事于宗庙。震为舟。在水上。故利涉。皆中爻象。</p><p>彖曰。涣亨 刚来而不穷。柔得位乎外而上同。王假有庙。王乃在中也。利涉大川。乘木有功也。</p><p>刚来居二。临一阴则陷。二阴则通。故曰不穷。四当位。上承一阳固吉。承二阳尤吉。上同者与小畜六四。升初六之上合志同也。言孚于五上也。震为舟。古刳木为舟。五乘之。故曰乘木。乘木即乘舟。</p><p>象曰。风行水上。涣。先王以享于帝立庙。</p><p>亨帝则礼仪繁盛。立庙则楹桷巍焕。皆属于文。正释卦义也。</p><p>初六。用拯马壮吉。</p><p>震为马。初承之。故曰拯马。郑云拯承也。拯马即承阳。震健故壮吉。此与明夷六二象同。故辞同。故象传皆以顺释之。拯顺也。</p><h3 id="象曰。初六之吉。顺也。" tabindex="-1">象曰。初六之吉。顺也。 <a class="header-anchor" href="#象曰。初六之吉。顺也。" aria-label="Permalink to “象曰。初六之吉。顺也。”">​</a></h3><p>言阴顺阳。以顺释拯义也。</p><p>九二。涣奔其机。悔亡。</p><p>焦循云。汉百官公卿表。虎贲郎注。贲读与奔同。据是奔贲古通。奔其机即贲其机。按机即几筵之几。庙中所用物。贲文饰也。艮为几。震为玄黄。故贲其机。得中。遇阴。故侮亡。</p><h3 id="象曰。涣奔其机。得愿也。" tabindex="-1">象曰。涣奔其机。得愿也。 <a class="header-anchor" href="#象曰。涣奔其机。得愿也。" aria-label="Permalink to “象曰。涣奔其机。得愿也。”">​</a></h3><p>阳遇重阴志行。故曰得愿。旧解无有知其故者。</p><p>六三。涣其躬。无悔。</p><p>艮为躬。涣其躬。即行有文也。得阳应。故涣其躬无悔。</p><h3 id="象曰。涣其躬。志在外也。" tabindex="-1">象曰。涣其躬。志在外也。 <a class="header-anchor" href="#象曰。涣其躬。志在外也。" aria-label="Permalink to “象曰。涣其躬。志在外也。”">​</a></h3><p>巽为志。应在上。故志在外。</p><p>六四。涣其群。元吉。</p><p>涣有丘。匪夷所思。坎为众为群。四体艮。艮为光明。在坎上。故涣其群。承阳故元吉。艮为丘。丘陵所以设险。今去坎险而复遇山险。故曰匪夷所思。夷平也。常也。言为恒常所不料也。</p><h3 id="象曰。涣其群元吉。光大也。" tabindex="-1">象曰。涣其群元吉。光大也。 <a class="header-anchor" href="#象曰。涣其群元吉。光大也。" aria-label="Permalink to “象曰。涣其群元吉。光大也。”">​</a></h3><p>遇阳故光大。按象曰光大。亦释涣为文。</p><p>九五。涣汗其大号。涣王居。无咎。</p><p>吴先生曰。汗连绵字。愚按上林赋。采色皓（左水）汗。注玉石符采映耀也。涣汗益与汗同。与涣烂亦同。巽为号令。涣汗其大号。即颁布光显其号令。如风之无不届也。艮为居。五君位。故曰王居。涣王居。言工居巍焕也。五履万民之上。故光大如此也。得中故无咎。</p><h3 id="象曰。王居无咎。正位也。" tabindex="-1">象曰。王居无咎。正位也。 <a class="header-anchor" href="#象曰。王居无咎。正位也。" aria-label="Permalink to “象曰。王居无咎。正位也。”">​</a></h3><p>五位中正。故曰正位。五无应。然无咎者。以得中也。</p><p>上九。涣其血去逖出。无咎。</p><p>血古文恤字。逖与惕音同通用。小畜六四。血去惕出。与此同也。诂选为远者非。应在三。坎为忧惕。王国维云。古易狄同字。山海大荒东经井竹书皆云王亥乇（左言）于有易。而楚辞天问作有狄。又简狄古今表作简遏。按汉书王商传。车无怵愁忧。师古云。狄（下心）古惕字。故虞翻注云。逖忧也。与小畜六四诂惕为忧同。是虞即以邀惕同字。上九应在三。三坎为忧惕。而上九高出卦上。去坎险即远。又不为互艮所止。与大畜上九义同。涣其光明貌。涣其恤去惕出。言光明在上。忧患自免也。句法与论语涣乎其有文章同。</p><h3 id="象曰。涣其血。远害也。" tabindex="-1">象曰。涣其血。远害也。 <a class="header-anchor" href="#象曰。涣其血。远害也。" aria-label="Permalink to “象曰。涣其血。远害也。”">​</a></h3><p>坎为害。上去三远。故曰远害。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
